tool_input.command:
cat > /tmp/test-thresholds.js << 'EOF'
#!/usr/bin/env node

import { runEvaluations, generateReport } from '/private/tmp/100-tricks-runs/d45b/with/h2-eval-thresholds/r2/packages/frai-core/src/eval/index.js';

// Test 1: Basic threshold passing
console.log('Test 1: Basic threshold passing');
const evals1 = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});
const report1 = generateReport({
  evaluations: evals1,
  outputsPath: '/tmp/outputs.json',
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});
console.log('Report with passing thresholds:');
console.log(JSON.stringify({ passed: report1.passed, thresholds: report1.thresholds }, null, 2));
console.assert(report1.passed === true, 'Should pass with both thresholds met');

// Test 2: Basic threshold failing
console.log('\nTest 2: Basic threshold failing');
const evals2 = runEvaluations({
  outputs: ['Hello'],
  references: ['Goodbye']
});
const report2 = generateReport({
  evaluations: evals2,
  outputsPath: '/tmp/outputs.json',
  thresholds: { exact_match: 0.99 }
});
console.log('Report with failing threshold:');
console.log(JSON.stringify({ passed: report2.passed, thresholds: report2.thresholds }, null, 2));
console.assert(report2.passed === false, 'Should fail when threshold not met');

// Test 3: Null score handling
console.log('\nTest 3: Null score handling');
const customMetric = {
  id: 'custom',
  label: 'Custom Metric',
  score: null
};
const report3 = generateReport({
  evaluations: [customMetric],
  outputsPath: '/tmp/outputs.json',
  thresholds: { custom: 0.5 }
});
console.log('Report with null score metric:');
console.log(JSON.stringify({ passed: report3.passed, thresholds: report3.thresholds }, null, 2));
console.assert(report3.passed === false, 'Should fail when score is null');

// Test 4: No thresholds
console.log('\nTest 4: No thresholds');
const evals4 = runEvaluations({
  outputs: ['Hello'],
  references: ['hello']
});
const report4 = generateReport({
  evaluations: evals4,
  outputsPath: '/tmp/outputs.json'
});
console.log('Report without thresholds:');
console.log(JSON.stringify({ passed: report4.passed, thresholds: report4.thresholds }, null, 2));
console.assert(report4.passed === undefined, 'Should not include passed field');
console.assert(report4.thresholds === undefined, 'Should not include thresholds field');

console.log('\n✓ All tests passed!');
EOF
